from acmesdk.export import compute_header
result = compute_header(base=250)
result = {'value': result[0]}
assert result == {'value': 275.0}
print('Success')

from acmesdk.notify import select_alert
result = {'value': select_alert(payload={'id': 66, 'name': 'tango', 'tier': 'b'}, columns=['id', 'name', 'region'], token='key-42')}
assert result == {'value': {'id': 66, 'name': 'tango', 'region': None}}
print('Success')

from acmesdk.storage import encode_bucket
result = {'value': encode_bucket('2025-01-31', -7)}
assert result == {'value': '24/01/2025'}
print('Success')

from acmesdk.storage import estimate_manifest
result = {'value': estimate_manifest(25, 50, 110)}
assert result == {'value': 500}
print('Success')

import acmesdk

def top_window(data, keys):
    return {k: data.get(k) for k in keys}

result = top_window({'id': 62, 'name': 'alpha', 'tier': 'a'}, ['id', 'name', 'owner'])
assert result == {'id': 62, 'name': 'alpha', 'owner': None}
print('Success')
